import java.util.List;
import java.util.UUID;

@Entity
@Table(name = "loan")
public class LoanJpaEntity {

    @Id
    private UUID id;

    @Column(nullable = false)
    private UUID bookId;

    @Column(nullable = false)
    private UUID memberId;

    @Column(nullable = false)
    private LocalDate loanedAt;

    @Column(nullable = false)
    private LocalDate dueAt;

    private LocalDate returnedAt;

    // 신용조회 결과. 조회 없이 만들어진 대출은 null 이다
    private Boolean creditApproved;
    private Integer creditScore;
    private String creditReasonCodes;
    private Instant creditCheckedAt;
    private String creditProviderName;
    private String creditProviderVersion;

    protected LoanJpaEntity() {
    }

    private LoanJpaEntity(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt,
                          LocalDate returnedAt, Boolean creditApproved, Integer creditScore,
                          String creditReasonCodes, Instant creditCheckedAt, String creditProviderName,
                          String creditProviderVersion) {
        this.id = id;
        this.bookId = bookId;
        this.memberId = memberId;
        this.loanedAt = loanedAt;
        this.dueAt = dueAt;
        this.returnedAt = returnedAt;
        this.creditApproved = creditApproved;
        this.creditScore = creditScore;
        this.creditReasonCodes = creditReasonCodes;
        this.creditCheckedAt = creditCheckedAt;
        this.creditProviderName = creditProviderName;
        this.creditProviderVersion = creditProviderVersion;
    }

    static LoanJpaEntity from(Loan loan) {
        CreditCheck creditCheck = loan.getCreditCheck();
        if (creditCheck == null) {
            return new LoanJpaEntity(loan.getId(), loan.getBookId(), loan.getMemberId(), loan.getLoanedAt(),
                    loan.getDueAt(), loan.getReturnedAt(), null, null, null, null, null, null);
        }
        return new LoanJpaEntity(loan.getId(), loan.getBookId(), loan.getMemberId(), loan.getLoanedAt(),
                loan.getDueAt(), loan.getReturnedAt(), creditCheck.approved(), creditCheck.score(),
                String.join(",", creditCheck.reasonCodes()), creditCheck.checkedAt(),
                creditCheck.providerName(), creditCheck.providerVersion());
    }

    // 신용조회 결과 없이 읽는 경우가 있으므로 creditCheck 는 조회 결과가 있을 때만 채운다
    Loan toDomain() {
        return Loan.reconstitute(id, bookId, memberId, loanedAt, dueAt, returnedAt, toCreditCheck());
    }

    private CreditCheck toCreditCheck() {
        if (creditApproved == null) {
            return null;
        }
        return new CreditCheck(creditApproved, creditScore, toReasonCodes(), creditCheckedAt,
                creditProviderName, creditProviderVersion);
    }

    private List<String> toReasonCodes() {
        if (creditReasonCodes == null || creditReasonCodes.isEmpty()) {
            return List.of();
        }
        return Arrays.asList(creditReasonCodes.split(","));
    }

    public UUID getId() {
        return id;
    }

    public UUID getBookId() {
        return bookId;
    }

    public UUID getMemberId() {
        return memberId;
    }

    public LocalDate getLoanedAt() {
        return loanedAt;
    }

    public LocalDate getDueAt() {
        return dueAt;
    }

    public LocalDate getReturnedAt() {
        return returnedAt;
    }

    public Boolean getCreditApproved() {
        return creditApproved;
    }

    public Integer getCreditScore() {
        return creditScore;
    }

    public String getCreditReasonCodes() {
        return creditReasonCodes;
    }

    public Instant getCreditCheckedAt() {
        return creditCheckedAt;
    }

    public String getCreditProviderName() {
        return creditProviderName;
    }

    public String getCreditProviderVersion() {
        return creditProviderVersion;
    }
}

