        return new LoanJpaEntity(loan.getId(), loan.getBookId(), loan.getMemberId(), loan.getLoanedAt(),
                loan.getDueAt(), loan.getReturnedAt(), creditCheck.approved(), creditCheck.score(),
                String.join(",", creditCheck.reasonCodes()), creditCheck.checkedAt(),
                creditCheck.providerName(), creditCheck.providerVersion());
    }

    // 신용조회 결과 없이 읽는 경우가 있으므로 creditCheck 는 조회 결과가 있을 때만 채운다
    Loan toDomain() {
        return Loan.reconstitute(id, bookId, memberId, loanedAt, dueAt, returnedAt, toCreditCheck());
    }

    private CreditCheck toCreditCheck() {
        if (creditApproved == null) {
            return null;
        }
        return new CreditCheck(creditApproved, creditScore, toReasonCodes(), creditCheckedAt,
                creditProviderName, creditProviderVersion);
    }

    private List<String> toReasonCodes() {
        if (creditReasonCodes == null || creditReasonCodes.isEmpty()) {
            return List.of();
        }
        return Arrays.asList(creditReasonCodes.split(","));
    }

    public UUID getId() {
        return id;
    }

    public UUID getBookId() {
        return bookId;
    }

    public UUID getMemberId() {
        return memberId;
    }

    public LocalDate getLoanedAt() {
        return loanedAt;
    }

    public LocalDate getDueAt() {
        return dueAt;
    }

    public LocalDate getReturnedAt() {
        return returnedAt;
    }

    public Boolean getCreditApproved() {
        return creditApproved;
    }

    public Integer getCreditScore() {
        return creditScore;
    }

    public String getCreditReasonCodes() {
        return creditReasonCodes;
    }

    public Instant getCreditCheckedAt() {
        return creditCheckedAt;
    }

    public String getCreditProviderName() {
        return creditProviderName;
    }

    public String getCreditProviderVersion() {
        return creditProviderVersion;
    }
}

